import Vue from 'vue';
import { Component, Prop } from 'vue-property-decorator';
import { IIconGradient, SvgIconType } from '../types';
import Calendar from '../../icons/calendar.svg';
import Chat from '../../icons/chat.svg';
import ChatFilled from '../../icons/chat-filled.svg';
import ChevronLeft from '../../icons/chevron-left.svg';
import MenuHandle from '../../icons/menu-1.svg';
import GameList from '../../icons/777-border.svg';
import GameListAlt from '../../icons/casino.svg';
import GameListFilled from '../../icons/777-border-filled.svg';
import GameListFilledAlt from '../../icons/casino-filled.svg';
import Exit from '../../icons/exit.svg';
import Cog from '../../icons/cog.svg';
import Close from '../../icons/close-border.svg';
import Speaker from '../../icons/speaker.svg';
import Mute from '../../icons/mute.svg';
import Unmute from '../../icons/unmute.svg';
import Dabber from '../../icons/dabber.svg';
import Timer from '../../icons/timer.svg';
import Open from '../../icons/open.svg';
import PlayerCount from '../../icons/player-count.svg';
import PrizeLeague from '../../icons/prize-league.svg';
import PrizeLeagueFilled from '../../icons/prize-league-filled.svg';

// import BackButton from '../../icons/back.svg';
import MenuButton from '../../icons/menu-2.svg';
import NewChatButton from '../../icons/chat-2.svg';
import NewCloseButton from '../../icons/close-no-border.svg';
import NewGameListButton from '../../icons/777-no-border.svg';
import NewPrizeLeagueButton from '../../icons/prize-league-2.svg';
import BingoGiGButton from '../../icons/bingo-gig.svg';

@Component({
    name: 'SvgIcon'
})
export default class SvgIcon extends Vue {
    @Prop({
        required: true,
        type: String
    })
    public icon: SvgIconType;

    @Prop({
        type: Boolean,
        required: false,
        default: false
    })
    public toggled: boolean;

    @Prop({
        type: Boolean,
        required: false,
        default: false
    })
    public fade: boolean;

    @Prop({
        type: Object,
        required: false
    })
    public gradient?: IIconGradient;

    public get svg() {
        const icon = this.getIcon();

        if (this.gradient) {
            return this.applyHightlightGradient(icon, this.gradient.start, this.gradient.end);
        }

        return icon;
    }

    private getIcon() {
        switch (this.icon) {
            case 'calendar':
                return Calendar;
            case 'chat':
                return this.toggled ? ChatFilled : Chat;
            case 'chevron-left':
                return ChevronLeft;
            case 'menu-handle':
                return MenuHandle;
            case 'game-list':
                return this.toggled ? GameListFilled : GameList;
            case 'game-list-alt':
                return this.toggled ? GameListFilledAlt : GameListAlt;
            case 'exit':
                return Exit;
            case 'cog':
                return Cog;
            case 'close':
                return Close;
            case 'speaker':
                return Speaker;
            case 'mute':
                return Mute;
            case 'unmute':
                return Unmute;
            case 'dabber':
                return Dabber;
            case 'timer':
                return Timer;
            case 'open':
                return Open;
            case 'player-count':
                return PlayerCount;
            case 'prize-league':
                return this.toggled ? PrizeLeagueFilled : PrizeLeague;
            case 'menu-2':
                return this.toggled ? ChevronLeft : MenuButton;
            case 'chat-2':
                return NewChatButton;
            case 'close-2':
                return NewCloseButton;
            case 'game-list-2':
                return NewGameListButton;
            case 'game-list-alt-2':
                return GameListAlt;
            case 'prize-league-2':
                return NewPrizeLeagueButton;
            case 'bingo-gig':
                return BingoGiGButton;
            default:
                throw new Error(`Could not find a matching SVG icon for "${this.icon}"`);
        }
    }

    private parseSVGString(content: string): HTMLElement {
        const parser = new DOMParser();
        const doc = parser.parseFromString(content, 'image/svg+xml');
        return doc.documentElement;
    }

    private applyHightlightGradient(svgString: string, colour1: string, colour2: string) {
        const svgElement = this.parseSVGString(svgString);
        const defs = document.createElement('defs');
        const gradient = document.createElement('linearGradient');
        gradient.id = 'grad1';
        defs.appendChild(gradient);
        svgElement.insertBefore(defs, svgElement.firstElementChild);

        // set the gradient direction
        gradient.setAttribute('x1', '0%');
        gradient.setAttribute('x2', '0%');
        gradient.setAttribute('y1', '0%');
        gradient.setAttribute('y2', '100%');

        // create stops for the gradient
        const stop1 = document.createElement('stop');
        stop1.setAttribute('offset', '0%');
        stop1.setAttribute('stop-color', colour1);
        gradient.appendChild(stop1);
        const stop2 = document.createElement('stop');
        stop2.setAttribute('offset', '25%');
        stop2.setAttribute('stop-color', colour1);
        gradient.appendChild(stop2);
        const stop3 = document.createElement('stop');
        stop3.setAttribute('offset', '75%');
        stop3.setAttribute('stop-color', colour2);
        gradient.appendChild(stop3);
        const stop4 = document.createElement('stop');
        stop4.setAttribute('offset', '100%');
        stop4.setAttribute('stop-color', colour2);
        gradient.appendChild(stop4);

        // replace fills with the new gradient
        svgElement.querySelectorAll('path').forEach((pathElement) => {
            (pathElement).setAttribute('fill', 'url(#grad1)');
        });

        return svgElement.outerHTML;
    }
}
